import{_ as a,o as e,c as s,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 16 章 团队协作：从个人到 AI 团队","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 16 章 团队协作：从个人到 AI 团队.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 16 章 团队协作：从个人到 AI 团队.md"}'),d={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 16 章 团队协作：从个人到 AI 团队.md"};function r(l,t,o,i,p,h){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="第-16-章-团队协作-从个人到-ai-团队" tabindex="-1">第 16 章 团队协作：从个人到 AI 团队 <a class="header-anchor" href="#第-16-章-团队协作-从个人到-ai-团队" aria-label="Permalink to &quot;第 16 章 团队协作：从个人到 AI 团队&quot;">​</a></h1><h2 id="_16-1-场景" tabindex="-1">16.1 场景 <a class="header-anchor" href="#_16-1-场景" aria-label="Permalink to &quot;16.1 场景&quot;">​</a></h2><p>第 8 章讲了怎么&quot;召唤&quot;团队。这一章讲怎么&quot;用好&quot;团队——因为建团只是开始，<strong>协作才是关键</strong>。</p><p>真实场景：一个产品上线任务，涉及需求梳理、技术方案、开发、测试、文档。一个人（哪怕是我）串行做，又慢又容易顾此失彼；拆给多个角色并行，质量和速度都能上一个台阶。</p><h2 id="_16-2-团队怎么分角色" tabindex="-1">16.2 团队怎么分角色 <a class="header-anchor" href="#_16-2-团队怎么分角色" aria-label="Permalink to &quot;16.2 团队怎么分角色&quot;">​</a></h2><p>分角色的原则：<strong>按任务的自然边界分，不按人数堆。</strong></p><table tabindex="0"><thead><tr><th>角色</th><th>职责</th><th>对应任务</th></tr></thead><tbody><tr><td>规划</td><td>拆解、定优先级</td><td>需求梳理、任务分配</td></tr><tr><td>开发</td><td>实现功能</td><td>写代码、改代码</td></tr><tr><td>测试</td><td>验证质量</td><td>写测试、跑测试、报告</td></tr><tr><td>文档</td><td>沉淀交付物</td><td>文档、教程、报告</td></tr><tr><td>评审</td><td>把关</td><td>检查交付物、找问题</td></tr></tbody></table><h2 id="_16-3-团队协作的标准流程" tabindex="-1">16.3 团队协作的标准流程 <a class="header-anchor" href="#_16-3-团队协作的标准流程" aria-label="Permalink to &quot;16.3 团队协作的标准流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Leader（我）拆解任务，定义每个子任务的产出标准</span></span>
<span class="line"><span>2. 分派：每个成员拿到明确的任务和验收标准</span></span>
<span class="line"><span>3. 并行执行：成员各自干活，互不干扰</span></span>
<span class="line"><span>4. 中间同步：关键节点向 Leader 汇报</span></span>
<span class="line"><span>5. 交叉验证：测试验开发、评审验全部</span></span>
<span class="line"><span>6. 汇总交付：Leader 整合成最终交付物</span></span>
<span class="line"><span>7. 复盘：哪些任务拆得好、哪些拆得差</span></span></code></pre></div><h2 id="_16-4-团队协作的常见坑" tabindex="-1">16.4 团队协作的常见坑 <a class="header-anchor" href="#_16-4-团队协作的常见坑" aria-label="Permalink to &quot;16.4 团队协作的常见坑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>坑</th><th>症状</th><th>解法</th></tr></thead><tbody><tr><td>任务拆不清</td><td>成员互相等</td><td>子任务边界明确，产出标准写清</td></tr><tr><td>没有中间检查</td><td>最后全错</td><td>关键节点设同步/检查点</td></tr><tr><td>角色重叠</td><td>两成员做同一件事</td><td>明确唯一负责人</td></tr><tr><td>需求漂移</td><td>做到一半改需求</td><td>变更先经过 Leader 重新排期</td></tr></tbody></table><h2 id="_16-5-我作为-leader-会怎么管" tabindex="-1">16.5 我作为 Leader 会怎么管 <a class="header-anchor" href="#_16-5-我作为-leader-会怎么管" aria-label="Permalink to &quot;16.5 我作为 Leader 会怎么管&quot;">​</a></h2><ul><li><strong>任务看板</strong>：谁在做什么、谁被谁阻塞、哪些完成了，一目了然；</li><li><strong>阻塞管理</strong>：发现成员被卡住，我来协调或换人；</li><li><strong>验收把关</strong>：每个子任务交付后我检查，不合格打回；</li><li><strong>及时收缩</strong>：任务变小了，关掉冗余成员，不让团队空转。</li></ul><h2 id="_16-6-单人还是团队-最终决策表" tabindex="-1">16.6 单人还是团队：最终决策表 <a class="header-anchor" href="#_16-6-单人还是团队-最终决策表" aria-label="Permalink to &quot;16.6 单人还是团队：最终决策表&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务很小/探索性质 → 单人</span></span>
<span class="line"><span>任务可拆成多个独立子任务 → 团队</span></span>
<span class="line"><span>任务有多个专业角色要求 → 团队</span></span>
<span class="line"><span>需求不明确，还在探索 → 先单人，想清楚再上团队</span></span></code></pre></div><h2 id="_16-7-练习" tabindex="-1">16.7 练习 <a class="header-anchor" href="#_16-7-练习" aria-label="Permalink to &quot;16.7 练习&quot;">​</a></h2><ol><li>把一个真实项目按&quot;角色边界&quot;拆成 3～5 个子任务；</li><li>让我按这个拆分建团并分派，观察每个成员的理解是否一致；</li><li>走完一轮&quot;派活 → 执行 → 验收&quot;，复盘拆分质量。</li></ol><blockquote><p>小结：AI 团队协作的本质是<strong>把复杂度结构化</strong>。Leader 的价值不在干活最多，而在拆得最清、验得最严。</p></blockquote>`,18)])])}const u=a(d,[["render",r]]);export{_ as __pageData,u as default};
